import React, { useState } from 'react';
import axios from 'axios';
import './Contact.css';
import PageTitle from '../PageTitle';

function Contact() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: '',
  });
  const [status, setStatus] = useState({ type: '', message: '' });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus({ type: '', message: '' }); // Reset status before sending

    try {
      const response = await axios.post('http://localhost:3001/api/notifications', formData);
      
      setStatus({ type: 'success', message: 'Mesajınız başarıyla gönderildi!' });
      setFormData({
        name: '',
        email: '',
        subject: '',
        message: '',
      });
    } catch (error) {
      console.error('Mesaj gönderilirken hata:', error);
      setStatus({ 
        type: 'error', 
        message: error.response?.data?.message || 'Mesaj gönderilirken bir hata oluştu.' 
      });
    }
  };

  return (
    <>
      <PageTitle title="İletişim" />
      <div>
        <div className="video-container">
          <video autoPlay muted loop>
            <source src="/beehiveloop.mp4" type="video/mp4" />
            Your browser does not support the video tag.
          </video>
          <div className="video-overlay">
            <h1>Welcome to Our Website</h1>
            <p>Discover our products and services</p>
            <a href="/urunumuz">
              <button className="anasayfabuton">Ürünümüz</button>
            </a>
          </div>
        </div>

        <div className="contact-page">
          <div className="contact-info-container">
            <div className="contact-info-left">
              <h2>Şirket Bilgileri</h2>
              <p><strong>Şirket İsmi:</strong> Beehive Inc.</p>
              <p><strong>Adres:</strong> 123 Bee Street, Honey City</p>
              <p><strong>Telefon:</strong> +90 123 456 7890</p>
            </div>
            <div className="contact-info-right">
              <h2>İletişim Formu</h2>
              {status.message && (
                <div
                  className={`alert ${
                    status.type === 'success' ? 'alert-success' : 'alert-error'
                  }`}
                >
                  {status.message}
                </div>
              )}
              <form onSubmit={handleSubmit}>
                <label>
                  İsim:
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    required
                    className="form-input"
                  />
                </label>
                <label>
                  E-posta:
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    className="form-input"
                  />
                </label>
                <label>
                  Konu:
                  <input
                    type="text"
                    name="subject"
                    value={formData.subject}
                    onChange={handleChange}
                    required
                    className="form-input"
                  />
                </label>
                <label>
                  Mesaj:
                  <textarea
                    name="message"
                    rows="5"
                    value={formData.message}
                    onChange={handleChange}
                    required
                    className="form-textarea"
                  ></textarea>
                </label>
                <button type="submit" className="submit-button">
                  Mesajı Gönder
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Contact;
